func TestReproLeak(t *testing.T) {
	baseline := liveGoroutines()
	p := &Pool{clients: makeTestClients(3)}
	p.Start()
	time.Sleep(50 * time.Millisecond)
	if liveGoroutines() <= baseline { t.Fatal("goroutines not leaked") }
}
